-- Catálogo Blue Haven. Ejecutar después de la migración de estructura.
insert into public.peces(nombre,rareza,velocidad,peso_seleccion,sprite,datos)
select p->>'nombre',(p->>'rareza')::int,(p->>'velocidad')::real,(p->>'pesoSeleccion')::real,p->>'sprite',p
from jsonb_array_elements($catalogo$[{"nombre":"Carpa","nombreCientifico":"Cyprinus carpio","rareza":1,"sprite":"Carpa.svg","habitat":"Aguas tranquilas de lagos y ríos lentos","alimentacion":"Omnívoro: plantas, insectos, gusanos","tamaño":"30-50 cm","peso":"1-3 kg","dificultad":"Fácil","descripcion":"La carpa es un pez resistente y común en aguas dulces. Es ideal para principiantes.","ceboRecomendado":"Lombriz o masa","datoCurioso":"Puede vivir hasta 20 años en condiciones ideales.","velocidad":1,"pesoSeleccion":55},{"nombre":"Trucha Arcoíris","nombreCientifico":"Oncorhynchus mykiss","rareza":2,"sprite":"Trucha.svg","habitat":"Ríos y arroyos de aguas frías y oxigenadas","alimentacion":"Carnívoro: insectos, pequeños peces, crustáceos","tamaño":"25-40 cm","peso":"0.5-2 kg","dificultad":"Media","descripcion":"Conocida por su coloración iridiscente. Es un pez deportivo muy valorado.","ceboRecomendado":"Mosca o cucharilla","datoCurioso":"Su nombre proviene de la franja rosada que recorre su costado.","velocidad":1.8,"pesoSeleccion":22},{"nombre":"Atún","nombreCientifico":"Thunnus thynnus","rareza":2,"sprite":"Atun.png","habitat":"Aguas abiertas del océano","alimentacion":"Carnívoro: peces pequeños, calamares, crustáceos","tamaño":"50-100 cm","peso":"5-20 kg","dificultad":"Media","descripcion":"Un nadador veloz y poderoso. Requiere equipo resistente.","ceboRecomendado":"Señuelo artificial","datoCurioso":"Puede nadar a 70 km/h y sumergirse a 1000 metros.","velocidad":2.3,"pesoSeleccion":18},{"nombre":"Pez Globo","nombreCientifico":"Tetraodontidae","rareza":2,"sprite":"Pez_Globo.png","habitat":"Aguas costeras tropicales y arrecifes poco profundos","alimentacion":"Invertebrados: caracoles, cangrejos y erizos","tamaño":"15-35 cm","peso":"0.4-1.5 kg","dificultad":"Media","descripcion":"Se infla ingiriendo agua para triplicar su tamaño ante cualquier peligro y disuadir atacantes.","ceboRecomendado":"Camarón o trozo de molusco","datoCurioso":"Posee tetrodotoxina, un veneno letal más potente que el cianuro, pero en Japón es un manjar.","velocidad":2,"pesoSeleccion":16},{"nombre":"Calamar","nombreCientifico":"Loligo vulgaris","rareza":3,"sprite":"Calamar.png","habitat":"Aguas costeras y mar abierto","alimentacion":"Carnívoro: peces pequeños, crustáceos","tamaño":"20-40 cm","peso":"0.5-2 kg","dificultad":"Difícil","descripcion":"Molusco cefalópodo de cuerpo alargado. Es escurridizo y rápido.","ceboRecomendado":"Señuelo luminoso","datoCurioso":"Tiene tres corazones y sangre azul.","velocidad":3.1,"pesoSeleccion":10},{"nombre":"Dragón del Lago","nombreCientifico":"Draco lacustris","rareza":3,"sprite":"Dragon.svg","habitat":"Aguas profundas y oscuras","alimentacion":"Desconocida","tamaño":"???","peso":"???","dificultad":"Difícil","descripcion":"Una criatura mítica que pocos pescadores han logrado ver.","ceboRecomendado":"???","datoCurioso":"Se dice que solo aparece en noches de luna llena.","velocidad":3,"pesoSeleccion":6},{"nombre":"Esturión Gigante","nombreCientifico":"Huso huso","rareza":4,"sprite":"Esturion.svg","habitat":"Aguas profundas de grandes ríos y lagos","alimentacion":"Carnívoro: peces, moluscos, crustáceos","tamaño":"100-200 cm","peso":"20-100 kg","dificultad":"Muy difícil","descripcion":"Un pez prehistórico de gran tamaño. Su captura es un desafío legendario.","ceboRecomendado":"Pez vivo o trozo de pescado","datoCurioso":"Existe desde la era de los dinosaurios, hace 200 millones de años.","velocidad":3.6,"pesoSeleccion":4},{"nombre":"Ballena Azul","nombreCientifico":"Balaenoptera musculus","rareza":4,"sprite":"Ballena_azul.png","habitat":"Océanos de todo el mundo","alimentacion":"Carnívoro: krill y pequeños peces","tamaño":"2000-3000 cm","peso":"100000-150000 kg","dificultad":"Extrema","descripcion":"El animal más grande que jamás ha existido en la Tierra.","ceboRecomendado":"???","datoCurioso":"Su corazón es del tamaño de un auto pequeño.","velocidad":4,"pesoSeleccion":2},{"nombre":"Pez Remo","nombreCientifico":"Regalecus glesne","rareza":5,"sprite":"Pez_remo.svg","habitat":"Aguas profundas del océano (200-1000m)","alimentacion":"Carnívoro: krill, pequeños peces, calamares","tamaño":"300-800 cm","peso":"20-50 kg","dificultad":"Extrema","descripcion":"El pez óseo más largo del mundo. Vive en las profundidades abisales.","ceboRecomendado":"???","datoCurioso":"Es considerado el origen de las leyendas de serpientes marinas.","velocidad":4.2,"pesoSeleccion":1}]$catalogo$::jsonb) p
on conflict(nombre) do update set rareza=excluded.rareza,velocidad=excluded.velocidad,peso_seleccion=excluded.peso_seleccion,sprite=excluded.sprite,datos=excluded.datos;
